 finding={'kind':'indicator','indicator_slug':'protected-land-share','name':'Land under durable conservation protection','value':x['protected_share_pct'],'unit':'% of jurisdiction land area','year':2026,'target':30,'level_pct':x['level_pct'],'scoring':{'threshold_ref':'biodiversity-loss.protected-land-share','function':'higher_is_better','inputs':{'value':x['protected_share_pct'],'target':30,'scale':30},'worked_math':f"protected share = {x['protected_m2']:.9f} / {x['land_m2']:.9f} × 100 = {x['protected_share_pct']:.12f}%; level_pct = (30 − {x['protected_share_pct']:.12f}) / 30 × 100 = +{x['level_pct']:.12f}"},'source':'Derived from CNRA CA Nature 30x30 Conserved Areas, Terrestrial (2026), official jurisdiction boundaries and Census 2026 land/water faces','source_url':cons,'source_tier':2,'evidence':{'snapshot_path':'evidence/biodiversity-loss-derived-2026.png','captured_at':now},'confidence':'medium','geographic_scale':'city' if tenant=='carmel' else 'county','notes':notes}
